struct HitCounter {
    private var times = [Int](repeating: 0, count: 300)
    private var counts = [Int](repeating: 0, count: 300)

    mutating func hit(_ timestamp: Int) {
        let i = timestamp % 300
        if times[i] != timestamp { times[i] = timestamp; counts[i] = 0 }
        counts[i] += 1
    }
    func getHits(_ timestamp: Int) -> Int {
        (0..<300).reduce(0) { $0 + (timestamp - times[$1] < 300 ? counts[$1] : 0) }
    }
}
